    quickrules_chess_1: "Setze den gegnerischen König schachmatt: Er steht im Schach und hat keinen legalen Zug, dem zu entkommen.",
    quickrules_chess_2: "Am Zug bewegst du eine deiner Figuren; jede Figurenart zieht auf ihre eigene Weise.",
    quickrules_chess_3: "Hat die Seite am Zug keinen legalen Zug und steht nicht im Schach, ist das Patt und die Partie ist remis.",
    quickrules_checkers_1: "Du gewinnst, wenn der Gegner keine Steine mehr hat oder am Zug keinen legalen Zug mehr machen kann.",
    quickrules_checkers_2: "Steine ziehen ein Feld diagonal vorwärts; geschlagen wird, indem du diagonal über einen angrenzenden gegnerischen Stein auf das freie Feld dahinter springst.",
    quickrules_checkers_3: "Ist ein Schlagzug möglich, musst du schlagen - ein normaler Zug ist dann nicht erlaubt.",
    quickrules_xiangqi_1: "Setze den gegnerischen General matt oder lass den Gegner am Zug ohne legalen Zug - auch das zählt hier als Sieg.",
    quickrules_xiangqi_2: "Die Steine stehen auf den Schnittpunkten, nicht auf Feldern, und am Zug bewegst du einen davon nach seiner eigenen Regel.",
