    nav_devices: "Geprüfte Geräte",
    about_devices_link: "Auf welchen E-Readern PaperGames geprüft ist - und wie du dein eigenes Gerät prüfst",
    devices_intro: "PaperGames läuft im Webbrowser eines E-Readers. Auf welchen Geräten es wirklich funktioniert, weiß man nur dort, wo es jemand ausprobiert und zurückgemeldet hat. Diese Seite listet diese Geräte auf und sagt genauso deutlich, was nicht geprüft ist.",
    devices_list_title: "Geräte mit Rückmeldung",
    devices_col_device: "Gerät",
    devices_col_screen: "Bildschirm",
    devices_col_checked: "Was geprüft wurde",
    devices_col_date: "Datum",
    devices_checked_user_report: "Im eigenen Browser des Geräts gespielt; gefundene Fehler wurden gemeldet",
    devices_checked_dev_device: "Entwicklungsgerät, jede Änderung wird darauf geprüft",
    devices_screen_unknown: "Modell nicht genannt",
    devices_untested: "Alle anderen Geräte sind ungeprüft. PaperGames läuft dort vielleicht, aber es hat sich noch niemand gemeldet.",
    devices_requirements: "PaperGames braucht einen aktuellen Browser mit JavaScript nach ES2015 (const, Pfeilfunktionen, Promises), fetch, Flexbox und CSS-Variablen sowie Service Workern für das Spielen ohne Netz. Nach allem, was bekannt ist, kann das der ältere Kindle-Browser nicht, ebenso der Kobo-Browser auf Basis von Qt WebKit 538; dort zeigt PaperGames nur einen kurzen Hinweis.",
    devices_check_title: "Prüf es auf deinem eigenen Gerät",
    devices_step1_title: "1. Seite öffnen",
    devices_step1_text: "Öffne PaperGames im eigenen Browser deines Readers. Achte darauf: Die Seite lädt, die Schrift ist scharf und am Rand wird nichts abgeschnitten.",
    devices_step2_title: "2. Ein Spiel starten",
    devices_step2_text: "Starte ein Spiel, zum Beispiel Sudoku oder Schach, und mach ein paar Züge. Achte darauf: Jeder Tipp trifft das gemeinte Feld, und das Brett passt ohne seitliches Scrollen auf den Bildschirm.",
    devices_step3_title: "3. Einstellungen öffnen",
    devices_step3_text: "Öffne die Einstellungen und schalte Schriftgröße und hohen Kontrast um. Achte darauf: Die Seite ändert sich sofort, und alles bleibt lesbar.",
    devices_step4_title: "4. Offline gehen",
    devices_step4_text: "Warte, bis die Startseite meldet, dass PaperGames offline bereit ist, schalte dann das WLAN aus und lade die Seite neu. Achte darauf: Die Seite und ein Spiel öffnen sich weiterhin.",
    devices_step5_title: "5. Später weitermachen",
    devices_step5_text: "Lass ein Spiel mittendrin liegen, schließ den Browser und öffne ihn später wieder. Achte darauf: Das Spiel steht genau dort, wo du aufgehört hast.",
    devices_report_title: "Zurückmelden",
    devices_report_text: "Schick den Namen deines Geräts und, wenn möglich, einen Bildschirmabzug von dem, was du gesehen hast, an diese Adresse:",
    devices_report_note: "Es gibt kein Formular und kein Konto, und nichts wird mitgeschrieben - es ist nur eine E-Mail.",
