    chess_history_intro: "Vom altindischen Kriegsspiel zum meistuntersuchten Brettspiel der Welt – Schach hat Kontinente und Jahrhunderte durchquert, um das zu werden, was es heute ist.",

    go_history_intro: "Go ist eines der ältesten Brettspiele, das noch in seiner ursprünglichen Form gespielt wird – ein Spiel um Gebiet und Steine, dessen Wurzeln vermutlich mehr als 2500 Jahre nach China zurückreichen.",

    checkers_history_intro: "Dame ist ein Spiel mit einfachen Regeln und großer strategischer Tiefe, entstanden aus der Kombination eines uralten Bretts mit einer neueren Art des Schlagens.",

    ur_history_intro: "Mit rund 4600 Jahren ist das Königliche Spiel von Ur eines der ältesten je entdeckten Brettspiele – und dank einer über zwei Jahrtausende reichenden Ermittlungsarbeit eines der wenigen antiken Spiele, das wir noch nach Regeln spielen können, die aus einer antiken Schriftquelle rekonstruiert wurden.",

    morris_history_intro: "Kaum ein Spiel wurde über so viele Jahrhunderte in so viele verschiedene Oberflächen eingeritzt wie Mühle – von ägyptischen Tempeldächern bis zu englischen Kathedral-Kreuzgängen.",

    backgammon_history_intro: "Der Stammbaum von Backgammon verläuft durch fast jede Zivilisation, die je Würfel geworfen hat – vom alten Mesopotamien und Rom bis zu den Kaffeehäusern des heutigen Nahen Ostens.",

    xiangqi_history_intro: "Chinesisches Schach teilt tiefe Wurzeln mit dem internationalen Schach, ging aber über mehr als tausend Jahre einen eigenen Weg, um zu dem Spiel zu werden, das heute von Hunderten Millionen Menschen gespielt wird.",

    mancala_history_intro: "Mancala ist nicht ein einzelnes Spiel, sondern eine ganze Spielfamilie – eine der ältesten der Welt, aufgebaut auf der einfachen, universellen Idee, Samen oder Steine zwischen Mulden zu verteilen.",

    reversi_history_intro: "Ein viktorianisches Gesellschaftsspiel, das fast ein Jahrhundert später in Japan unter neuem Namen und mit fester Startaufstellung zurückkehrte.",

    fourinarow_history_intro: "Eine simple, von der Schwerkraft angetriebene Idee, die zu einem weltweiten Klassiker wurde.",

    gomoku_history_intro: "Ein simples Reihenspiel, dessen Einfachheit Wettkampfspieler dazu zwang, seine Regeln zu ändern.",
    tictactoe_history_intro: "Wohl das bekannteste Spiel für Papier und Stift überhaupt – mit Wurzeln im alten Rom und einem Platz in der Geschichte der Computer.",

    senet_history_intro: "Eines der ältesten je gefundenen Brettspiele – und eines, dessen genaue Regeln seit Jahrtausenden verloren sind.",

    shogi_history_intro: "Japans Variante der Schachfamilie – und die einzige große Variante, bei der ein geschlagener Stein das Spiel nicht verlässt, sondern zur schlagenden Seite wechselt.",

    sudoku_history_intro: "Anders als jedes andere Spiel in dieser Sammlung hat Sudoku überhaupt keine alte Herkunft – das Rätsel in seiner heutigen Form stammt erst aus dem Jahr 1979.",

    pegsolitaire_history_intro: "Ein Einzelspieler-Rätsel, alt genug für eine eigene Ursprungslegende, und Gegenstand eines der überraschenderen Ergebnisse der Unterhaltungsmathematik.",

    minesweeper_history_intro: "Ein Rätsel, dessen prägendste Regel – ein völlig sicherer erster Zug – erst zum Standard wurde, als Computer statt einer gedruckten Seite ein frisches Brett auf Abruf erzeugen konnten.",

    nonogram_history_intro: "Ein Logikrätsel, das in Japan etwa zur selben Zeit zweimal unabhängig voneinander erfunden wurde – benannt nach einer seiner beiden Erfinderinnen und Erfinder.",

    twenty48_history_intro: "Ein Spiel, das fast vollständig aus den Ideen anderer Spiele besteht, an einem Wochenende entstand und von mehr Menschen kopiert wurde als vielleicht jedes Browserspiel zuvor.",

    mahjong_history_intro: "Ein Einzelspieler-Zuordnungsspiel, benannt nach einem völlig anderen Vierspielerspiel, dessen Optik es sich leiht, mit dem es aber ansonsten fast nichts gemein hat.",

