    update_banner_more_notes: "Und weitere Verbesserungen.",
    release_v223: "Das Speichern für offline ist robuster, Spiele sind in Familien geordnet, Domino hat die Variante „Dreiecke“, und „Wer hat den Kuchen?“ hat das Motiv „Katzen und Fisch“ und gibt mehr Hinweise.",
    release_v224: "Kartenduell: vier gleich starke Decks, gegen den Computer oder zu zweit an einem Gerät.",
    release_v225: "Märchen-Schurken: sechs Bösewichte aus den Grimm-Märchen mit eigenen Zielen, für 2 bis 4 Spieler.",
    release_v226: "Waldsiedlung: Waldtiere bauen durch die Jahreszeiten ein Dorf, für 1 bis 4 Spieler.",
    release_v227: "Abenteuerbuch: ein Rollenspiel für eine Person – erstelle eine Figur und erkunde eine Höhle, einen Turm oder einen Wald.",
    release_v228: "Ein kleiner Link in der Fußzeile der Startseite führt zu Quillwild, einem neuen Projekt in Arbeit.",
    release_v229: "Die Startseite ist jetzt kürzer, die Kategorien haben eigene Seiten.",
    release_v230: "Kartenduell: alle Karten haben jetzt Bilder.",
    release_v234: "Tangram hat die neue Stufe „Nur Umriss“ mit 29 neuen Figuren.",
    release_v235: "Suchbild mit neun Räumen und über 40 neuen Zeichnungen; „Wer hat den Kuchen?“ mit einer Familie und mit Kindern und einem Schatz.",
    release_v236: "Suchbild mit Badezimmer, Keller und Schlafzimmer; „Wer hat den Kuchen?“ mit fünf weiteren Räumen und sieben neuen Möbelstücken.",
    release_v237: "„Neue Spiele“ zeigt jetzt die 10 neuesten Spiele.",
    release_v241: "Waldsiedlung hat neue Regeln, einen neuen Namen und überarbeitete Beschreibungen; alte Spielstände der Waldsiedlung werden verworfen.",
    release_v242: "Das Spiel hat einen neuen Namen und eine neue Adresse; alte Adressen leiten weiter.",
    release_v243: "Der Offline-Speicher lädt weniger neu; Arabisch hat Abstände, aktive Knöpfe sind schwarz, „Mischen“ fragt nach, und Regelseiten haben oben einen Zurück-Link.",
    release_v244: "Spiele öffnen direkt spielbereit; das Ergebnisfenster hat „Nochmal spielen“; „Neues Spiel“ steht neben dem Brett; Schach hat einen eigenen Knopf für zwei Spieler.",
    release_v245: "Spielseiten haben einen einzeiligen Kopf und keine Seiten-Navigation; „Einstellungen“ ist ins Menü gewandert; das Steuerfeld schließt nach dem Start, damit mehr Bretter auf den Bildschirm passen.",
    release_v246: "Spielkarten auf allen Kategorieseiten sind große Tippflächen; die Kinderseite zeigt alle Kinderspiele auf einer Seite mit großen Symbolen; „Großes Feld“ macht kleine Bretter besser tippbar; Kuchen steht nicht mehr bei den Kinderspielen.",
    release_v249: "Seiten laden schneller, weil sie weniger Daten brauchen. Neue Spiele: Kleeberg und Weidefreunde.",
    release_v250: "In Steckwürfeln lassen sich die Löcher antippen, Klappenkasten zeigt, was der Computer zugeklappt hat, und Bingo erlaubt bis zu vier Computergegner. Die Knöpfe bei Durak und Skat funktionieren wieder.",
    release_v251: "Neues Spiel: Zoowurf. Weidefreunde erklärt sich jetzt mit Bildern, Schwimmen zeigt den richtigen Spieler am Zug, das Kleeberg-Brett ist nicht mehr abgeschnitten, und Link-Vorschauen zeigen keine Spielzahl mehr.",
    release_v253: "Zoowurf: Du legst die Pfoten jetzt selbst auf die Karte, und nach dem Zug des Computers siehst du seine Karte, Würfel und Pfoten und tippst auf Weiter.",
    release_v254: "Die Lizenz hat sich geändert: PaperGames darf jetzt nur noch nicht kommerziell genutzt werden (PolyForm Noncommercial 1.0.0). Für das Spielen ändert sich nichts.",
    release_v255: "Waldsiedlung: Spielbeschreibung und Regeln nennen jetzt überall Lehm, Samen und Federn und die Senke.",
    release_v256: "Offline: Fällt das Internet mitten in einer Aktualisierung aus, bleibt die alte Version jetzt vollständig und funktioniert weiter; die Startseite sagt in klaren Worten, was fehlt und was zu tun ist.",
    release_v257: "Titel und Beschreibung der Startseite nennen jetzt Kindle, Kobo, Tolino und Boox (Suchergebnisse und Linkvorschau).",
    release_v258: "In einem Browser, der für PaperGames zu alt ist (zum Beispiel im älteren Kindle-Browser), zeigt jede Seite jetzt einen kurzen Hinweis statt einer kaputten oder leeren Seite.",
    release_v259: "Sudoku und Killer-Sudoku starten und erzeugen neue Rätsel auf langsamen E-Readern schneller, und Seiten zeigen vor deiner Sprache nicht mehr kurz englischen Text.",
    release_v260: "Jedes Spiel hat unten einen Link „Idee oder Fehler melden“, der dein E-Mail-Programm mit Spiel, Version und Sprache öffnet. Im Rommé nennt der Hinweis zum Jokertausch jetzt die Hausregel.",
    release_v261: "Rommé: Passt ein Joker an beide Enden einer Folge, wählst du jetzt das Ende. Dazu zwei neue Optionen: Hand-Rommé (alle Karten auf einmal auslegen, die Strafpunkte der anderen zählen doppelt) und Klopfen auf eine abgelegte Karte gegen zwei oder drei Computer.",
    release_v264: "Ludo: ein Brett für 6 Spieler. Wegesperre: ein schnelles Brett mit Ruhefeldern und bis zu 6 Spieler. Hex: Schwarz und Weiß mit klarer Farbwahl. Bildanleitung für Verbinden, Schwarzer Peter und Leiterspiel. Lizenzhinweise, Datenschutzerklärung und drei Geschichtsseiten überarbeitet.",
    release_v265: "Wegesperre: wenige, normal viele oder viele Sperrklötze wählen. Kleine Knöpfe sind jetzt groß genug zum Antippen, und drei weitere Spiele haben ein großes Spielfeld. Bildanleitung für Krieg und Paare. Sternjagd nennt, wer beginnt. Ludo-Texte und 15 Geschichtsseiten geprüft und berichtigt.",
    release_v266: "Sternjagd: Bei 2 Spielern ist der Zweite beim ersten Mal zweimal hintereinander dran, abschaltbar. 15 weitere Geschichtsseiten geprüft und berichtigt.",
    release_v267: "Teuflische Sieben heißt jetzt Glückskette und hat eigene Regeln: Zahlen 1 bis 10, ein Bonus für Zahlen in Folge, sechs neue Sonderkarten und Ziele von 60, 90 oder 120 Punkten. Eine nach den alten Regeln gespeicherte Partie beginnt neu.",
    release_v263: "Das Würfel-Laufspiel mit Sperrklötzen auf den Wegen hat einen neuen Namen: „Wegesperre“. Regeln, Spielstände und Statistik bleiben gleich.",
    release_v262: "Minesweeper: Die Uhr bleibt verborgen, außer du schaltest „Zeit anzeigen“ ein, und zu viele Flaggen werden klar benannt. Hex: neue Tauschregel (standardmäßig an). Domino: Der Vorrat-Knopf ist immer zu sehen und groß genug zum Antippen. Schach: ein Hinweis, dass der Online-Modus Internet und ein Lichess-Konto braucht.",
    release_v252: "Bingo, Steckwürfeln, Klappenkasten, Zoowurf und Weidefreunde erklären sich jetzt mit Bildern, Zoowurf hat eine Stufe für Anfänger, und das Kuchenbrett nennt seine Räume mit Zahlen und hat größere Felder.",
    release_v248: "Sieben neue Spiele (Bingo, drei Würfelspiele und drei Kinderrätsel), eine neue schwerste Stufe bei Pfeile, ein Hinweisknopf bei Katzenplätze, bessere Suche und die Seite Kartenspiele.",
    release_v247: "Alle Spiele verwenden dieselben Namen und Statustexte („Gegen den Computer“, „Zu zweit an einem Gerät“, „Neues Spiel“, „Du bist dran“); jede Spielseite hat einen Home-Knopf; „Rückgängig“ nimmt in 32 Spielen deinen Zug und die Antwort des Computers zurück.",
    release_v240: "Die Spielnamen wurden in allen 12 Sprachen geändert.",
    release_v239: "Geschützte Spielnamen wurden aus Regeln und Beschreibungen der Geschichtsseiten entfernt.",
    release_v238: "Die Kurzregeln passen jetzt zum gewählten Kuchenmotiv und zum Suchbild.",
    release_v233: "Pfeile auf Schwer: Gleitpfeile, 11 × 11 Felder und die neue Stufe Meister mit drei Herzen.",
    release_v232: "Zugvorschläge lassen sich in den Einstellungen abschalten, und „Wer hat den Kuchen?“ hat drei neue Motive.",
    release_v231: "Finde die Unterschiede hat jetzt auch ein Suchbild.",
