    home_coming_soon_title: "Demnächst",
    home_coming_soon_intro: "Weitere Spiele, die für ein zukünftiges Update in Betracht gezogen werden:",
    home_coming_soon_multiplayer_title: "Strategiespiele zu zweit",
    home_coming_soon_solo_title: "Einzelspieler-Rätsel",
    game_four_in_a_row: "Vier in einer Reihe",
    home_four_in_a_row_desc: "Wirf Scheiben ein und verbinde als Erster vier in einer Reihe. Lokal zu zweit oder gegen die eingebaute KI.",
    game_gomoku: "Gomoku (Fünf in einer Reihe)",
    home_gomoku_desc: "Bringe als Erster fünf Steine in eine Reihe, auf einem Go-großen Brett. Lokal zu zweit oder gegen die eingebaute KI.",
    game_tictactoe: "Tic-Tac-Toe",
    home_tictactoe_desc: "Drei in einer Reihe auf einem 3x3-Feld – der Klassiker für Papier und Stift. Lokal zu zweit oder gegen die eingebaute KI, die auf „Schwer“ nie verliert.",
    tictactoe_board_label: "Tic-Tac-Toe-Spielfeld",
    game_alquerque: "Alquerque",
    home_alquerque_desc: "Der mittelalterliche Vorfahre von Dame: je 12 Steine auf einem 5x5-Brett aus Linien, geschlagen wird durch Überspringen, und Schlagen ist Pflicht. Lokal zu zweit oder gegen die eingebaute Engine.",
    alquerque_board_label: "Alquerque-Brett",
    msg_keep_jumping: "Spring mit diesem Stein weiter.",
    alquerque_history_intro: "Ein kleines Sprungspiel auf einem Brett aus Linien, aufgeschrieben im Spanien des 13. Jahrhunderts - und der Vorfahre von Dame.",
    game_pairs: "Paare",
    home_pairs_desc: "Decke zwei Karten auf und finde die Paare: das klassische Kartenpaar-Suchspiel mit einfachen schwarz-weißen Formen, Tieren, Obst und Gemüse oder Fahrzeugen. Allein gegen die Zahl der Züge, zu zweit an einem Gerät oder gegen die eingebaute KI.",
    game_futoshiki: "Futoshiki",
    home_futoshiki_desc: "Fülle das Gitter so, dass jede Zeile und Spalte jede Zahl einmal enthält – und jedes Zeichen zwischen zwei Feldern auf die kleinere Zahl zeigt. 4x4 bis 6x6, frisch erzeugt mit eindeutiger Lösung.",
    futoshiki_board_label: "Futoshiki-Spielfeld",
    futoshiki_size_label: "Gittergröße",
    futoshiki_history_intro: "Ein japanisches Zahlenrätsel, dessen Name einfach Ungleichung bedeutet: ein lateinisches Quadrat mit kleinen Zeichen zwischen den Feldern.",
    game_foxandgeese: "Fuchs und Gänse",
    home_foxandgeese_desc: "Das mittelalterliche Jagdspiel auf dem Kreuz mit 33 Punkten: ein Fuchs gegen 13 Gänse. Spiel eine der beiden Seiten, lokal zu zweit oder gegen die eingebaute Engine.",
    foxandgeese_board_label: "Fuchs-und-Gänse-Brett",
    foxandgeese_history_intro: "Ein Jagdspiel aus dem mittelalterlichen Europa: ein Fuchs, eine Schar Gänse und ein kreuzförmiges Brett.",
    game_seega: "Seega",
    home_seega_desc: "Ein ägyptisches Setz- und Einklemmspiel auf 5x5 Feldern: Erst setzen beide Seiten ihre 12 Steine, dann wird durch Einklemmen geschlagen. Lokal zu zweit oder gegen die eingebaute Engine.",
    seega_board_label: "Seega-Brett",
    seega_history_intro: "Ein Spiel aus Ägypten, beschrieben 1836: Setz deine Steine zu zweit, dann klemm den Gegner zwischen zwei eigenen ein.",
    game_romme: "Rommé",
    home_romme_desc: "Das deutsche Rommé mit zwei Blatt und sechs Jokern: Sätze und Folgen auslegen, an jede Auslage anlegen und alle Karten loswerden. 2 bis 4 Personen, gegen den Computer oder an einem Gerät.",
    romme_history_intro: "Das Rommé, wie es in Deutschland mit zwei Blatt und Jokern gespielt wird – eines der vielen Spiele, in denen man Sätze und Folgen sammelt.",
