    seo_t_game: "{s} auf E-Ink – offline spielen, ohne Werbung",
    seo_title_index: "PaperGames – {games} kostenlose Spiele für E-Ink-Reader",
    seo_desc_index: "{games} kostenlose Spiele für E-Ink-Reader mit Browser, getestet auf Tolino, Boox und PocketBook: Schach, Sudoku, Go und mehr. Offline, ohne Werbung, 12 Sprachen.",
    seo_title_about: "Über PaperGames – {games} kostenlose Brettspiele für E-Ink",
    seo_desc_about: "Warum es PaperGames gibt, wie es gebaut ist und wie du das Projekt unterstützen kannst. Eine kostenlose, werbefreie Sammlung von {games} klassischen Brett- und Rätselspielen, auch offline.",
    nav_calm: "Ruhig spielen",
    about_calm_link: "Ruhig spielen: keine Animationen, keine Töne, keine Werbung",
    calm_intro: "PaperGames ist für ruhiges Spielen gebaut. Das heißt konkret:",
    calm_point_1: "Keine Animationen: Nichts blinkt, gleitet oder springt. Jede Änderung erscheint in einem Schritt.",
    calm_point_2: "Keine Töne.",
    calm_point_3: "Keine Werbung, keine Benachrichtigungen. Ein Konto brauchst du nicht – nur Online-Schach läuft über ein Lichess-Konto.",
    calm_point_4: "Kein Tracking, keine Cookies. Spielstände und Statistik bleiben im Browser auf deinem Gerät.",
    calm_point_5: "Gebaut für E-Ink-Lesegeräte: dunkle Schrift auf hellem Grund, und Unterschiede werden nie nur durch Grau oder Farbe gezeigt.",
    calm_point_6: "Kein Zeitdruck. Ausnahmen: Stadt, Land, Fluss mit wählbarer Rundenzeit (ab Werk aus), die mitlaufende Uhr bei Minesweeper und die Bedenkzeit beim Online-Schach über Lichess.",
    calm_point_7: "Nach dem ersten Öffnen läuft alles ohne Internet, sofern der Browser das unterstützt – außer Online-Schach.",
    calm_point_8: "Auch für Kinder: In den Spielen gibt es nichts zu kaufen und nichts zu teilen. Die Seite „Über“ enthält einen freiwilligen Spenden-Link zu PayPal.",
    calm_kids: "Spiele für Kinder, die meisten ohne Lesen spielbar:",
    seo_title_calm: "Ruhig spielen – reizarme Spiele ohne Werbung und Animationen | PaperGames",
    seo_desc_calm: "PaperGames spielt ruhig: keine Animationen, keine Töne, keine Werbung, keine Benachrichtigungen, kein Konto nötig, kein Tracking. Für E-Ink gebaut, läuft offline.",
    seo_title_games: "Alle Spiele – PaperGames",
    seo_desc_games: "Alle {games} kostenlosen Brett- und Rätselspiele von PaperGames durchsuchen und sortieren, alphabetisch oder nach Art.",
    seo_title_guide: "Einrichtung | PaperGames",
    seo_desc_guide: "So richtest du PaperGames auf deinem E-Reader oder Tablet ein: im Browser öffnen, zum Startbildschirm hinzufügen und ganz offline weiterspielen.",
    seo_title_devices: "Getestete Geräte – auf welchen E-Readern PaperGames läuft | PaperGames",
    seo_desc_devices: "Auf welchen E-Readern PaperGames nachweislich läuft, was noch nicht getestet ist und wie du dein eigenes Gerät prüfst und Rückmeldung gibst – ohne Formular, ohne Konto.",
    seo_title_impressum: "Impressum | PaperGames",
    seo_desc_impressum: "Impressum von PaperGames, einer kostenlosen Sammlung von {games} Offline-Brettspielen für E-Reader, betrieben von Christopher Müller.",
    seo_title_datenschutz: "Datenschutzerklärung | PaperGames",
    seo_desc_datenschutz: "Datenschutzerklärung von PaperGames: keine Cookies, keine Analyse, keine Werbung. Nur lokaler Speicher, dazu die freiwillige Lichess-Anmeldung für Online-Schach.",
    seo_title_stats: "Deine Statistik | PaperGames",
    seo_desc_stats: "Deine Siege, Niederlagen und Unentschieden in allen Spielen von PaperGames, nur auf deinem eigenen Gerät gezählt.",
    seo_title_history: "Bibliothek der Spielgeschichte | PaperGames",
    seo_desc_history: "Woher jedes Spiel der PaperGames-Sammlung stammt, vom alten Ägypten bis zum letzten Jahrzehnt, ungefähr in zeitlicher Reihenfolge.",
    romme_split_rule_label: "Hausregel: Folgen teilen",
    romme_choice_extend: "An die Auslage anlegen",
    romme_choice_split: "Folge teilen",
    msg_t_rm_splits: "{p} teilt eine Folge mit der {s}.",
    msg_t_rm_you_split: "Du teilst eine Folge mit der {s}.",
    msg_rm_split_set: "Sätze werden nicht geteilt.",
    msg_rm_split_short: "Beide Folgen müssen nach dem Teilen mindestens drei Karten haben.",
