    game_shogi: "Shogi",
    home_shogi_desc: "Japanisches Schach, bei dem geschlagene Figuren die Seite wechseln und wieder mitspielen. Lokal zu zweit oder gegen die eingebaute KI.",
    game_card_tactics: "Kartentaktik",
    home_card_tactics_desc: "Ein schnelles, elegantes Duell, entschieden durch fünf wechselnde Zugkarten. Lokal zu zweit oder gegen die eingebaute KI.",
    cardtactics_neutral_card: "Nächste Karte:",


    cardtactics_history_intro: "Eine moderne Ergänzung der Familie abstrakter Strategiespiele, aufgebaut auf einer kleinen Abwandlung schachähnlicher Bewegung: Statt dass jede Figur eine feste Zugweise hat, entscheidet ein gemeinsames Kartendeck von Zug zu Zug, was möglich ist.",

    game_hnefatafl: "Hnefatafl (Wikingerschach)",
    home_hnefatafl_desc: "Ein asymmetrisches nordisches Spiel: Der König muss entkommen, die Angreifer müssen ihn einschließen. Lokal zu zweit oder gegen die eingebaute KI.",

    hnefatafl_history_intro: "Eine der ältesten Brettspielfamilien Nordeuropas, gespielt in der Wikingerwelt über Jahrhunderte, bevor das Schach dort überhaupt ankam.",
    game_tablut: "Tablut",
    home_tablut_desc: "Das größte und am besten dokumentierte Tafl-Spiel: ein 9x9-Brett, auf dem der König eine Ecke erreichen muss, während die Angreifer ihn zuerst einschließen wollen.",
    tablut_history_intro: "Das am besten dokumentierte Mitglied der gesamten Tafl-Familie, dank des Notizbuchs eines Naturforschers aus dem 18. Jahrhundert.",


    game_wall_maze: "Mauerlabyrinth",
    home_wall_maze_desc: "Wettlaufe zur gegenüberliegenden Seite und baue dabei Mauern, um den Gegner zu blockieren. Lokal zu zweit oder gegen die eingebaute KI.",

    wallmaze_history_intro: "Mauerlabyrinth ist ein modernes abstraktes Strategiespiel, das aus einem simplen Wettlauf über ein Gitter durch ein paar Mauern ein echtes Duell der Taktik macht.",
