    msg_hex_computer_swaps: "Der Computer tauscht: Er spielt jetzt Schwarz, und der erste Stein gehört ihm.",


    hex_history_intro: "Ein seltener Fall, in dem dasselbe einfache, elegante Spiel zweimal erfunden wurde – nach der üblichen Darstellung unabhängig voneinander – von zwei Personen, die später aus ganz unterschiedlichen Gründen bekannt werden sollten.",

    game_halma: "Halma",
    home_halma_desc: "Bringe alle deine Figuren als Erster ins gegnerische Lager. Lokal zu zweit oder gegen die eingebaute KI.",

    halma_history_intro: "Eine amerikanische Überarbeitung eines älteren englischen Spiels, seit weit über einem Jahrhundert beliebt als einfaches Wettrennen, das leicht zu lernen ist, aber dennoch sorgfältige Planung belohnt.",
    game_sternhalma: "Sternhalma",
    home_sternhalma_desc: "Bringe alle zehn deiner Murmeln über das sternförmige Brett in die gegenüberliegende Spitze. Lokal zu zweit oder gegen die eingebaute KI.",
    sternhalma_history_intro: "Ein Nachfahre des älteren Spiels Halma mit sternförmigem Brett, vermarktet unter einem exotischen Namen, der nichts mit seinem tatsächlichen Ursprung zu tun hat.",

    game_dotsandboxes: "Punkte und Kästchen (Käsekästchen)",
    home_dotsandboxes_desc: "Ziehe Linien zwischen Punkten, um Kästchen zu vervollständigen und für dich zu beanspruchen – wer ein Kästchen vervollständigt, ist gleich noch einmal am Zug. Auf 4 × 4, 5 × 5, 6 × 6 oder 8 × 8 Kästchen, lokal zu zweit oder gegen die eingebaute KI.",
    dotsandboxes_new_game: "Neues Spiel",
    dotsandboxes_board_size_label: "Brettgröße",
    dotsandboxes_board_size_4: "4 × 4 Kästchen (kurze Partie)",
    dotsandboxes_board_size_5: "5 × 5 Kästchen",
