    dotsandboxes_history_intro: "Ein Papier-und-Bleistift-Spiel, das über hundert Jahre alt ist – und ein echtes Thema ernsthafter mathematischer Forschung.",
    game_fanorona: "Fanorona",
    home_fanorona_desc: "Madagaskars Nationalspiel: Ziehe Steine entlang der Linien eines 5x9-Gitters, um durch Annäherung oder Rückzug zu schlagen. Lokal zu zweit oder gegen die eingebaute Engine.",
    game_konane: "Konane",
    home_konane_desc: "Hawaiianisches Damespiel: ein volles Brett mit abwechselnden Steinen und orthogonalen Sprungketten, eröffnet durch ein einzigartiges Zwei-Stein-Entfernungsritual. Lokal zu zweit oder gegen die eingebaute Engine.",

    fanorona_history_intro: "Das Nationalbrettspiel Madagaskars - und Gegenstand echten kulturellen Stolzes und mancher Legende.",

    fanorona_choose_capture_type: "Sowohl ein Schlag durch Annäherung als auch durch Rückzug ist möglich - wähle einen:",
    fanorona_capture_approach_btn: "Durch Annäherung schlagen",
    fanorona_capture_withdrawal_btn: "Durch Rückzug schlagen",
    fanorona_continue_capturing: "Du kannst mit diesem Stein weiterschlagen oder hier aufhören.",
    fanorona_done_capturing_btn: "Fertig mit Schlagen",
    game_ludo: "Ludo",
    home_ludo_desc: "Das klassische kreuzförmige Wettlaufspiel, ein Nachfahre des alten indischen Pachisi. Spiele selbst eine Farbe gegen computergesteuerte Gegner, oder spielt lokal abwechselnd am selben Gerät: 2-4 Spieler auf dem klassischen Brett, bis zu 6 auf dem Brett mit sechs Armen.",
    ludo_mode_hotseat: "Zu zweit an einem Gerät",
    ludo_num_players: "Spieler:",
    ludo_board_label: "Brett:",
    ludo_board_4: "4 Spieler (klassisch)",
    ludo_board_6: "6 Spieler",
    ludo_roll_die: "Würfeln",
    ludo_history_intro: "Ein moderner, massenproduzierter Nachfahre eines der ältesten Brettspiele Indiens.",

    konane_history_intro: "Ein traditionelles Spiel der Ureinwohner Hawaiis aus Steinen und Strategie, direkt in das Land eingeschlagen, auf dem es gespielt wurde.",
    konane_continue_jumping: "Du kannst mit diesem Stein weiterspringen oder hier aufhören.",
    konane_done_jumping_btn: "Fertig mit Springen",
    game_surakarta: "Surakarta",
    home_surakarta_desc: "Das indonesische Fangspiel mit den Schleifenbahnen: Ein einfacher Schritt schlägt nie, nur ein Zug, der über eine der 4 Eckschleifen des Bretts läuft. Lokal zu zweit oder gegen die eingebaute Engine.",
    surakarta_history_intro: "Ein traditionelles indonesisches Brettspiel, benannt nach genau der Stadt auf Java, aus der es vermutlich stammt.",

    game_marblepush: "Kugelschub",
    home_marblepush_desc: "Schiebe 6 gegnerische Kugeln vom sechseckigen Spielbrett, um zu gewinnen. Lokal zu zweit oder gegen den Computer, mit allen Regeln zum Schieben und zu seitlichen Reihenzügen.",
    marblepush_history_intro: "Ein Schiebespiel für zwei auf einem sechseckigen Brett, bei dem man nur schlagen kann, indem man gegnerische Kugeln über den Rand drängt.",
    marblepush_selection_hint: "Tippe auf ein hervorgehobenes Feld, um diese Auswahl zu bewegen, oder setze sie unten zurück.",
    marblepush_clear_selection_btn: "Auswahl aufheben",

    game_baghchal: "Bagh-Chal",
    home_baghchal_desc: "Nepals traditionelles Jagdspiel: 4 Tiger gegen 20 Ziegen auf einem quadratischen 5x5-Brett im Alquerque-Stil. Lokal zu zweit oder gegen die eingebaute Engine, wahlweise auf beiden Seiten.",

    baghchal_history_intro: "Nepals bekanntestes traditionelles Brettspiel: Tiger jagen Ziegen über ein Gitter aus Linien - mit Wurzeln, die weit älter sind als jede schriftliche Aufzeichnung der Regeln.",


    game_amazons: "Amazonen",
    home_amazons_desc: "Bewege eine damenähnliche Amazone und schieße dann von ihrem neuen Feld aus einen dauerhaften Pfeil ab, um das Brett Stück für Stück zu versperren. Lokal zu zweit oder gegen die eingebaute KI.",
    amazons_history_intro: "Das Spiel der Amazonen ist ein modernes abstraktes Strategiespiel, bei dem es darum geht, sich Stück für Stück Raum zu sichern, indem man das Brett dauerhaft versperrt.",

    game_sudoku: "Sudoku",
    home_sudoku_desc: "Fülle ein 9x9-Gitter mit Ziffern, sodass jede Zeile, Spalte und jedes 3x3-Feld die Zahlen 1–9 genau einmal enthält. Frisch erzeugt mit eindeutiger Lösung, in drei Schwierigkeitsgraden.",
    game_peg_solitaire: "Solitär",
    home_peg_solitaire_desc: "Springe mit Stiften übereinander, bis nur noch einer übrig ist – auf dem englischen Kreuz oder einem von mehreren anderen Brettern, vom 6x6-Quadrat bis zu Wieglebs Kreuz mit 45 Feldern.",
    game_minesweeper: "Minesweeper",
    home_minesweeper_desc: "Decke mit Hilfe der Zahlenhinweise alle sicheren Felder auf, ohne eine versteckte Mine auszulösen.",
    game_nonograms: "Nonogramme",
    home_nonograms_desc: "Nutze Zeilen- und Spalten-Zahlenhinweise, um Feld für Feld ein verstecktes Bild aufzudecken. Ein frisches, eindeutig lösbares Rätsel in drei Größen.",
    game_2048: "2048",
    home_2048_desc: "Schiebe und verschmelze nummerierte Kacheln, um 2048 zu erreichen, bevor das Brett voll ist. Danach weiterspielen, um den Bestwert noch weiter zu treiben.",
    game_mahjong_solitaire: "Mahjong Solitaire",
    home_mahjong_solitaire_desc: "Räume das gestapelte Steine-Layout ab, indem du gleiche Paare findest. Jedes Blatt wird so erzeugt, dass immer eine Lösung existiert.",
    game_freecell: "FreeCell",
    home_freecell_desc: "Der klassische Karten-Solitär, bei dem sich fast jede Runde mit den richtigen Zügen gewinnen lässt. Mit vollen Mehrfachzügen und Sammeln auf die Basen per Klick.",

    freecell_new_game: "Neues Spiel",
    freecell_collect: "Auf Basen sammeln",


    freecell_history_intro: "Eine jahrhundertealte Familie von Kartenspielen, deren bekannteste Variante ungewöhnlicherweise vor allem wegen eines ganz bestimmten Stücks Software aus den 1990ern berühmt ist.",

    game_yatzy: "Yatzy",
    home_yatzy_desc: "Das klassische Würfelspiel mit 5 Würfeln. Würfle bis zu dreimal pro Zug, halte die Würfel, die du behalten willst, und trage alle 15 Kategorien in den Spielbogen ein, um die höchste Punktzahl zu erreichen.",

