    bullsandcows_history_intro: "Ein reines Logikspiel zum Knacken eines Codes, ganz ohne Gegenspieler, das als Rätselspiel mit Papier und Stift begann und später zum Lieblingsthema von Informatikern wurde, die untersuchen, wie man eine verborgene Antwort möglichst geschickt findet.",
