    home_calcudoku_desc: "Fülle das Gitter so, dass jede Zeile und Spalte jede Ziffer einmal enthält und jeder Käfig mit seinem Rechenzeichen seine Zielzahl ergibt. Größen 4x4 bis 7x7, drei Schwierigkeitsstufen.",
