    home_animalsudoku_desc: "Sudoku für Kinder mit Tieren statt Zahlen: 4 x 4 oder 6 x 6, jedes Tier einmal in jeder Zeile, Spalte und jedem Block. Tier wählen, Feld antippen – ganz ohne Lesen.",
