    game_shapesort: "Formen sortieren",
    home_shapesort_desc: "Ein ruhiges Sortierrätsel: Verschiebe die Steine zwischen den Röhren, bis in jeder Röhre nur noch eine Form liegt. 4 bis 10 Steine pro Röhre. Formen statt Farben, darum gut auf Schwarz-Weiß-E-Ink; Zurücknehmen so oft du willst.",
