    home_war_desc: "Das einfache Kartenspiel nur mit Glück: Beide decken eine Karte auf, die höhere gewinnt beide – und bei Gleichstand ist Krieg. 32 Karten, gegen den Computer, ohne Entscheidungen; kurz über 30 Runden oder bis zum Ende.",
