    sl_history_intro: "Das Leiterspiel stammt aus einer Familie indischer Würfel-Brettspiele und kam in den 1890er-Jahren nach England.",
    quickrules_snakesladders_1: "Würfle: Deine Figur zieht von selbst weiter, Feld für Feld in Schlangenlinie.",
