    game_blockers: "Wegesperre",
    home_blockers_desc: "Ein Würfelrennen zum Ziel oben auf dem Plan für 2 bis 6 Spieler: Sperrklötze sperren die Wege, und wer auf einem landet, setzt ihn den anderen in den Weg. Gegen den Computer oder mit Freunden an einem Gerät.",
    bl_level_label: "Stufe",
    bl_board_aria: "Spielplan Wegesperre",
    bl_history_intro: "Wegesperre ist ein Laufspiel bei PaperGames; es greift alte Elemente der Würfel-Laufspiele auf, etwa das Hinauswerfen und das Versperren des Weges.",
    quickrules_blockers_1: "Würfle und ziehe eine Figur genau so viele Felder auf den Wegen in Richtung Ziel oben.",
    quickrules_blockers_2: "Über einen Sperrklotz darf keine Figur ziehen. Landest du auf einem Sperrklotz, setzt du ihn auf ein anderes freies Feld – jemand anderem in den Weg. Vor dem Spiel wählst du, ob wenige, normal viele oder viele Sperrklötze auf dem Brett stehen.",
    quickrules_blockers_3: "In der oberen Hälfte (runde Felder) schickst du eine fremde Figur zurück in ihr Haus, wenn du auf ihr landest; auf den eckigen Feldern darunter sind Figuren sicher. Die erste Figur im Ziel gewinnt – oder, wenn vor dem Spiel so gewählt, wer zuerst alle Figuren im Ziel hat.",
    quickrules_blockers_4: "Brett „Schnell“ (vor dem Spiel wählen): kleiner, 4 Figuren pro Person; auf einem Ruhefeld (Achteck) ist eine Figur sicher, dort passt nur eine Figur hin und kein Sperrklotz.",
    msg_bl_stone_place: "Tippe auf ein freies Feld für den Sperrklotz (nicht in der untersten Reihe).",
