    game_blackjack: "17 und 4",
    home_blackjack_desc: "Das Kartenspiel um 21 gegen die Bank: Karten ziehen oder stehen bleiben, aber nicht über 21 kommen. Zwei Varianten: 17 und 4 mit 32 Karten und Blackjack mit 52. Gespielt wird mit Chips, die nur Punkte im Spiel sind.",
