    bj_restart: "Neu anfangen mit 100 Chips",
    bj_history_intro: "Spiele um die 21 sind alt: Die erste schriftliche Erwähnung steht in einem Buch von Miguel de Cervantes, und um 1899 bekam die amerikanische Form den Namen Blackjack.",
    quickrules_blackjack_1: "Nimm Karte für Karte und komm so nah an 21 heran, wie du kannst.",
