    home_skat_desc: "Deutschlands klassisches Kartenspiel zu dritt: du gegen zwei Computer, mit Reizen, Skat, Handspielen, Grand und Null und Spielwerten nach den offiziellen Regeln. Französisches oder deutsches Blatt; eine Liste über viele Spiele.",
