    game_schafkopf: "Schafkopf",
    home_schafkopf_desc: "Das bayerische Kartenspiel zu viert mit deutschem Blatt: du gegen drei Computer bei Sauspiel, Wenz und Solo, mit Schneider, Schwarz, Laufenden und Punkteliste. Nur Punkte, kein Geld.",
    sf_history_intro: "Schafkopf wird 1782 in Sachsen zum ersten Mal erwähnt; das erste eindeutig bayerische Spiel ist für 1849 belegt.",
    quickrules_schafkopf_1: "Sag „weiter“ oder ein Spiel an: Sauspiel (du rufst eine Sau, wer sie hat, spielt mit dir), Wenz oder Solo.",
    quickrules_schafkopf_2: "Ober und Unter sind die hohen Trümpfe (im Wenz nur die Unter); Farbe bedienen. Die gerufene Sau muss kommen, wenn ihre Farbe gespielt wird.",
    quickrules_schafkopf_3: "Die Spieler brauchen 61 der 120 Augen. Schneider, Schwarz und Laufende erhöhen den Preis.",
