    game_bridge: "Bridge",
    home_bridge_desc: "Kontrakt-Bridge zu viert: du und dein Computer-Partner gegen zwei Computer. Geführtes Reizen mit Knöpfen, der Strohmann offen auf dem Tisch, Wertung als Chicago (vier Spiele) oder Robber.",
    br_history_intro: "Bridge stammt vom Whist ab; die ersten bekannten Regeln („Biritch, or Russian Whist“) sind von 1886, Kontrakt-Bridge von 1925.",
    quickrules_bridge_1: "Reize, wie viele Stiche über sechs deine Seite macht, mit einer Trumpffarbe oder Sans Atout; das höchste Gebot wird der Kontrakt.",
    quickrules_bridge_2: "Der Alleinspieler spielt beide Hände: Der Strohmann (sein Partner) liegt offen. Farbe bedienen; der höchste Trumpf gewinnt.",
    quickrules_bridge_3: "Erfülle den Kontrakt für Punkte; fehlen Stiche, punkten die Gegner. Chicago: vier Spiele.",
