    game_tenpairs: "Zehner-Paare",
    home_tenpairs_desc: "Das Papier-und-Bleistift-Rätsel zum Zahlenstreichen: Paare, die gleich sind oder zusammen 10 ergeben und sich sehen. Kommst du nicht weiter, legst du die offenen Ziffern nach. Klassischer Start oder Zufall in drei Stufen.",
    tp_history_intro: "Ein Papier-und-Bleistift-Rätsel aus Schulheften; woher es stammt, ist nicht belegt.",
    quickrules_tenpairs_1: "Tippe zwei Ziffern an, die gleich sind (3 und 3) oder zusammen 10 ergeben (3 und 7), um sie zu streichen.",
    quickrules_tenpairs_2: "Sie müssen sich sehen: nebeneinander waagerecht, senkrecht oder schräg oder nur mit gestrichenen Feldern dazwischen; waagerecht auch über das Zeilenende.",
    quickrules_tenpairs_3: "Kein Paar mehr? Tippe auf Nachlegen: Die offenen Ziffern werden hinten noch einmal angehängt (höchstens 5-mal). Streiche alle Ziffern, um zu gewinnen.",
    tp_start_label: "Start:",
