    msg_tp_hint_none: "Tipp: Kein Paar mehr – tippe auf Nachlegen.",
    msg_tp_hint: "Tipp: Die beiden markierten Ziffern kannst du streichen.",
    msg_tp_crossed_out: "gestrichen",
