    msg_t_tp_add: "Nachlegen (noch {n})",
    game_mathcross: "Rechengitter",
    home_mathcross_desc: "Setze die Zahlen 1 bis 9 je einmal ein, sodass jede Zeile und jede Spalte aufgeht – gerechnet wird von links nach rechts. Drei Stufen, immer genau eine Lösung, ohne Raten lösbar.",
    mc_history_intro: "Ein Zahlenrätsel aus Rechnungen in Zeilen und Spalten, verwandt mit dem uralten magischen Quadrat aus den Zahlen 1 bis 9.",
    quickrules_mathcross_1: "Setze die Zahlen 1 bis 9 in die Kästchen, jede genau einmal.",
    quickrules_mathcross_2: "Jede Zeile und jede Spalte muss ihr Ergebnis ergeben. Gerechnet wird von links nach rechts (oben nach unten) – ohne Punkt vor Strich: 3 + 4 × 2 = 14.",
    quickrules_mathcross_3: "Tippe auf ein Kästchen, dann auf eine Zahl. Ein Haken oder Kreuz zeigt, ob eine volle Zeile oder Spalte aufgeht.",
    game_cardduel: "Kartenduell",
    home_cardduel_desc: "Ein Fantasy-Kartenspiel für zwei Magier: Wesen und Zauber, vier fertige Decks aus Wald, Feuer, Wasser und Stein. Gegen den Computer in drei Stufen oder zu zweit an einem Gerät.",
    quickrules_cardduel_1: "Bring den gegnerischen Magier von 20 Lebenspunkten auf 0.",
    quickrules_cardduel_2: "Jede Runde hast du 1 Kraft mehr (bis 10). Tippe eine Karte an, dann „Ausspielen“: Wesen bleiben liegen, Zauber wirken einmal.",
    quickrules_cardduel_3: "Zum Angreifen tippst du ein bereites Wesen (dicker Rahmen) an und dann das Ziel. Ein Wächter muss zuerst angegriffen werden.",
