    home_villains_desc: "Jeder spielt einen Bösewicht aus den Grimm-Märchen mit eigenem Ziel – Hexe, Wolf, Rumpelstilzchen und mehr –, und die anderen stellen ihm Helden in den Weg. 2 bis 4 Spieler, gegen den Computer oder an einem Gerät.",
    quickrules_villains_1: "Erreiche als Erster das Ziel deines Schurken – die Zielkarte zeigt, was noch fehlt.",
    quickrules_villains_2: "Tippe jeden Zug einen anderen Ort deines Gebiets an, nutze dann seine Aktionen (Gold, Karte spielen, Märchenwende …) und beende den Zug.",
    quickrules_villains_3: "Helden, die dir die anderen schicken, sperren einen Ort, bis du sie besiegst; mit der Märchenwende schickst du den anderen Helden.",
