    vl_goal_rumpel: "Beende einen Zug mit {n} Gold, während der Bote nicht in deinem Gebiet ist – niemand darf deinen Namen kennen. Stroh zu Gold spinnen: Wirf eine Karte ab für {s} Gold.",
