    ab_item_silverbook: "Silbernes Buch",
    ab_item_goldenseed: "Goldener Samen",
    ab_room_cave_1: "Wasser tropft von der Decke in einen kleinen, klaren Tümpel.",
    ab_room_cave_2: "Blaue Kristalle wachsen aus den Wänden und leuchten sanft.",
    ab_room_cave_3: "Ein enger Gang. Du musst dich unter einem niedrigen Felsen ducken.",
    ab_room_cave_4: "Alte Loren stehen auf rostigen Schienen. Hier hat vor langer Zeit jemand gearbeitet.",
    ab_room_cave_5: "Die Höhle öffnet sich zu einer hohen Halle. Deine Schritte hallen.",
    ab_room_cave_6: "Glitzernder Sand bedeckt den Boden. Er knirscht unter deinen Stiefeln.",
    ab_room_cave_7: "Aus einem Spalt im Fels weht ein kalter Wind.",
    ab_room_cave_8: "Hier wachsen Pilze, so groß wie Stühle. Sie riechen nach Erde.",
    ab_room_cave_9: "Ein unterirdischer Bach rauscht in einer Steinrinne vorbei.",
    ab_room_cave_10: "Seltsame Zeichnungen von Sternen bedecken eine Wand.",
    ab_room_cave_11: "Tropfsteine hängen wie Eiszapfen aus Stein von der Decke.",
    ab_room_cave_12: "Eine kleine Seitenhöhle. Jemand hat hier eine alte Decke liegen lassen.",
    ab_room_cave_13: "Der Weg führt über glatte Felsen, rutschig vom Moos.",
    ab_room_cave_14: "In einer dunklen Ecke schlafen Fledermäuse. Du gehst auf Zehenspitzen.",
    ab_room_cave_15: "Eine runde Kammer mit glattem Boden, wie poliert.",
    ab_room_cave_16: "Grünes Moos taucht die Wände in einen blassen Schein.",
    ab_room_cave_17: "Hier führte einmal eine Hängebrücke hinüber. Nur die Pfosten sind noch da.",
    ab_room_cave_18: "Hier ist die Luft warm. Irgendwo tief unten grollt es.",
    ab_room_cave_19: "Überall liegen Kristallsplitter, als wäre ein großer Stein geplatzt.",
    ab_room_cave_20: "Ein stiller Winkel. Deine Lampe wirft lange Schatten.",
    ab_room_tower_1: "Regale voller staubiger Bücher reichen bis an die Decke.",
    ab_room_tower_2: "Eine Wendeltreppe windet sich nach oben. Die Stufen knarren.",
    ab_room_tower_3: "Raben sitzen auf einem Balken und sehen dich mit glänzenden Augen an.",
    ab_room_tower_4: "Eine alte Küche. Über einer kalten Feuerstelle hängt ein Kessel.",
    ab_room_tower_5: "Durch ein rundes Fenster siehst du tief unten den Wald.",
    ab_room_tower_6: "Ein Arbeitszimmer mit einem riesigen Schreibtisch. In den Töpfchen ist die Tinte eingetrocknet.",
    ab_room_tower_7: "Hinter einer Glaswand drehen sich langsam Zahnräder. Tick, tack.",
    ab_room_tower_8: "Ein langer Flur mit Bildnissen. Ihre Augen scheinen dir zu folgen.",
    ab_room_tower_9: "Ein Raum voller Landkarten. Eine davon zeigt einen Turm wie diesen.",
    ab_room_tower_10: "Auf einem Tisch brennen Kerzen, obwohl niemand hier zu sein scheint.",
    ab_room_tower_11: "Eine Vorratskammer mit Gläsern voller getrockneter Kräuter und bunter Pulver.",
    ab_room_tower_12: "Der Wind pfeift durch einen kaputten Fensterladen.",
    ab_room_tower_13: "Ein Musikzimmer. Eine Harfe spielt ganz von allein einen Ton.",
    ab_room_tower_14: "Eine schmale Brücke aus Brettern führt von einer Wand zur anderen.",
    ab_room_tower_15: "Ein Schlafzimmer mit Himmelbett. Die Vorhänge sind voller Löcher.",
    ab_room_tower_16: "Eine Werkstatt mit einem Fernrohr, das zum Himmel zeigt.",
    ab_room_tower_17: "Schwarze Federn liegen überall auf dem Boden.",
    ab_room_tower_18: "An der Wand hängt ein Spiegel, aber er zeigt ein anderes Zimmer.",
    ab_room_tower_19: "Ein kleiner Balkon. Hier oben riecht der Wind nach Regen.",
    ab_room_tower_20: "Ein kühler Saal mit einem Boden aus schwarzen und weißen Fliesen.",
    ab_room_forest_1: "Nebel hängt zwischen den Bäumen. Du siehst kaum deine Hand.",
    ab_room_forest_2: "Eine Lichtung voller Blumen. Bienen summen in der Sonne.",
    ab_room_forest_3: "Ein alter Pfad, zugewachsen mit Farn.",
    ab_room_forest_4: "Ein hohler Baum, so groß, dass man darin stehen kann.",
    ab_room_forest_5: "Ein kleiner Teich. Frösche springen ins Wasser, als du kommst.",
    ab_room_forest_6: "Wurzeln, dick wie Arme, ziehen sich über den Weg.",
    ab_room_forest_7: "Hoch oben in den Baumkronen singen Vögel.",
    ab_room_forest_8: "Ein Kreis aus weißen Steinen liegt im Gras.",
    ab_room_forest_9: "Brombeersträucher wachsen an einer Steinmauer entlang.",
    ab_room_forest_10: "Der Boden ist weich und grün vom Moos. Es ist ganz still.",
    ab_room_forest_11: "Ein umgestürzter Stamm liegt wie eine Brücke über einer Senke.",
    ab_room_forest_12: "Eine verlassene Hütte. Die Tür steht offen.",
    ab_room_forest_13: "Hohe Kiefern knarren im Wind.",
    ab_room_forest_14: "Kleine Lichter tanzen über einem Moor.",
    ab_room_forest_15: "Eine riesige Eiche mit einem Gesicht, das in ihre Rinde geschnitzt ist.",
    ab_room_forest_16: "Pilze wachsen in einem genauen Kreis.",
    ab_room_forest_17: "Ein Bach plätschert über glatte Kiesel.",
    ab_room_forest_18: "Ein dunkles Dickicht. Äste kratzen an deinen Ärmeln.",
    ab_room_forest_19: "Ein sonniger Hügel. Von hier siehst du den Nebel unten wie ein Meer.",
    ab_room_forest_20: "Alte Steinstufen führen zwischen zwei Birken hindurch.",
    home_adventurebook_desc: "Ein Rollenspiel für eine Person: Erstelle eine Figur, erkunde Raum für Raum eine Höhle, einen Turm oder einen Wald, würfle Proben und Kämpfe und bring einen verlorenen Schatz zurück. Leicht, Mittel oder Schwer.",
    quickrules_adventurebook_1: "Erstelle eine Figur, finde dann den Schatz des Ortes und bring ihn zurück zum Eingang.",
    quickrules_adventurebook_2: "Proben: Zwei Würfel plus ein Wert müssen die angegebene Zahl erreichen. Das Ergebnis steht mit der Rechnung da.",
    quickrules_adventurebook_3: "Kämpfe laufen in Runden: Angreifen, Verteidigen, Gegenstand, Klassenfähigkeit oder Fliehen. Das Spiel speichert nach jedem Schritt.",
