    game_pentomino: "Legepuzzle",
    home_pentomino_desc: "Lege die zwölf Teile aus je fünf Quadraten in ein Rechteck – drehen und spiegeln per Tippen, ohne Ziehen. Freies Legen in vier Feldgrößen oder mit vorgegebenen Startteilen und genau einer Lösung.",
    pt_history_intro: "Zwölf Teile aus je fünf Quadraten: ein Rätsel, das Henry Dudeney 1907 veröffentlichte und dem Solomon Golomb 1953 den Namen „Pentominos“ gab.",
    quickrules_pentomino_1: "Fülle das Rechteck mit den Teilen; jedes Feld wird genau einmal bedeckt.",
    quickrules_pentomino_2: "Wähle ein Teil unter dem Feld, drehe oder spiegle es und tippe dann auf das Feld, wohin sein Punkt soll. Tippe ein gelegtes Teil an, um es wieder aufzunehmen.",
    quickrules_pentomino_3: "Bei „Startteile vorgegeben“ liegen einige Teile fest, und die übrigen passen auf genau eine Weise.",
    pt_mode_label: "Spielart:",
    pt_mode_free: "Freies Legen",
    pt_mode_fixed: "Startteile vorgegeben",
    pt_size_label: "Feld:",
