    pt_aria_empty: "leer",
    pt_aria_piece: "Teil {L}",
    pt_aria_fixed: "fest",
    pt_aria_laid: "gelegt",
    pt_win_title: "Gelöst!",
    msg_pt_choose: "Wähle ein Teil unter dem Feld.",
    msg_pt_place: "Drehe oder spiegle es bei Bedarf und tippe dann dorthin, wohin sein Punkt soll.",
    msg_pt_nofit: "Das Teil passt dort nicht.",
    msg_pt_fixed: "Dieses Teil liegt fest.",
    msg_t_pt_picked: "Teil {s} aufgenommen.",
    msg_pt_won: "Das Rechteck ist voll – gelöst!",
    msg_t_pt_hint_place: "Tipp: Teil {s} gehört an die markierte Stelle.",
    msg_t_pt_hint_remove: "Tipp: Teil {s} versperrt die Lösung – nimm es weg.",
    msg_pt_hint_none: "Tipp: Kein Weg gefunden – nimm ein Teil weg.",
    msg_t_pt_info: "Gelegt: {n} von {m} Teilen",
    game_arrows: "Pfeile",
    home_arrows_desc: "Tippe einen Pfeil an, und er gleitet aus dem Feld – wenn kein anderer Pfeil im Weg ist. Räume das ganze Feld; jedes Rätsel ist lösbar, mit Rückgängig und Tipps und ohne Zeitdruck. Auf Schwer und Meister gleiten blockierte Pfeile vor und können festsitzen.",
    aw_history_intro: "Teile, die nur in eine Richtung gleiten dürfen, sind Verwandte der Schiebepuzzles, die 1880 große Mode wurden; die Version mit Pfeilen ist ein junges Rätsel.",
    quickrules_arrows_1: "Tippe einen Pfeil an: Er verlässt das Feld in seine Richtung, wenn der Weg bis zum Rand frei ist.",
    quickrules_arrows_2: "Steht ein anderer Pfeil im Weg, passiert nichts – nimm zuerst diesen heraus. Auf Schwer und Meister gleitet er stattdessen bis zu diesem Pfeil vor.",
    quickrules_arrows_3: "Räume das ganze Feld. Jedes Rätsel ist lösbar; „Tipp“ markiert einen Pfeil, der hinaus kann.",
    aw_win_title: "Feld geräumt!",
    aw_aria_cell: "Zeile {R}, Spalte {C}",
    aw_aria_empty: "leer",
    aw_aria_arrow: "Pfeil nach {D}",
    aw_dir_0: "oben",
    aw_dir_1: "rechts",
    aw_dir_2: "unten",
    aw_dir_3: "links",
    msg_aw_start: "Tippe einen Pfeil an, um ihn aus dem Feld zu schicken.",
    tg_level_outline: "Nur Umriss",
    game_loosen: "Ringe lösen",
    home_loosen_desc: "Ineinander verhakte Ringe, jeder mit einer Lücke: Dreh sie – verhakte Ringe drehen sich andersherum mit –, bis einer nach dem anderen frei wird. Drei Stufen, mit den wenigsten Zügen, Rückgängig und Tipps.",
    lr_history_intro: "Ringrätsel sind alt – die chinesischen Ringe wurden schon um 1500 beschrieben; diese flache Form mit Lücken ist neu.",
    quickrules_loosen_1: "Tippe einen Ring an: Er dreht sich eine Vierteldrehung im Uhrzeigersinn, die mit ihm verhakten Ringe andersherum.",
    quickrules_loosen_2: "Ein Ring ist frei, wenn seine Lücke dort sitzt, wo der verhakte Ring oben liegt – tippe ihn an, dann kommt er heraus.",
    quickrules_loosen_3: "Nimm alle Ringe heraus; die Ringe an den Enden zuerst. „Tipp“ zeigt einen Zug.",
    lr_win_title: "Alle gelöst!",
