    dg_dice_none: "Noch nicht gewürfelt",
    dg_roll: "Würfeln",
    game_weidefreunde: "Weidefreunde",
    home_weidefreunde_desc: "Ein Karten-Würfelspiel für Kinder: Würfle mit dem Tierwürfel und sammle die fünf Bauernhoftiere – Kuh, Schaf, Schwein, Huhn und Pferd – auf deiner eigenen Weide. Nur Bilder, kein Lesen nötig, kein Zeitlimit. Gegen den Computer oder mit bis zu vier Personen an einem Gerät.",
    weidefreunde_history_intro: "Spiele mit Bildern statt Zahlen und Karten zum Sammeln gehören zu den ersten Spielen kleiner Kinder – dieses verbindet beides.",
    quickrules_weidefreunde_1: "Würfle. Der Würfel zeigt ein Tier oder den Bauern.",
    quickrules_weidefreunde_2: "Liegt die Karte dieses Tiers im Hof und fehlt es auf deiner Weide, wandert sie zu dir. Mit dem Bauern nimmst du eine beliebige Karte, die dir fehlt. Sonst schickst du eine Hofkarte zurück.",
    quickrules_weidefreunde_3: "Wer zuerst alle fünf Tiere auf der Weide hat, gewinnt.",
    wf_animal_0: "Kuh",
    wf_animal_1: "Schaf",
    wf_animal_2: "Schwein",
