    wf_yard: "Hof",
    wf_roll: "Würfeln",
    wf_roll_hint: "Würfle.",
    wf_pick_hint: "Bauer! Tippe eine Karte an, die dir noch fehlt.",
    wf_swap_hint: "Keine Karte für dich. Tippe eine Karte an, um sie zurückzuschicken.",
    wf_last_take: "{name}: {animal} genommen.",
    wf_last_farmer: "{name}: Bauer! {animal} genommen.",
