    wf_full_pasture: "Eine Weide ist voll: Alle fünf Tiere sind da.",
    wf_howto_title: "So funktioniert es",
    wf_howto_1: "Würfle. Der Würfel zeigt ein Tier oder den Bauern.",
    wf_howto_2: "Die Karte dieses Tiers wandert vom Hof auf deine Weide, wenn du das Tier noch nicht hast.",
    wf_howto_3: "Bauer: Nimm eine beliebige Hofkarte, die dir noch fehlt. Keine Karte für dich: Schicke eine Hofkarte zurück.",
    wf_howto_4: "Ziel: alle fünf Tiere auf deiner Weide. Wer sie zuerst hat, gewinnt.",
    wf_howto_show: "Wie geht das?",
    wf_howto_hide: "Erklärung ausblenden",
    howto_title: "So funktioniert es",
    howto_show: "Wie geht das?",
    howto_hide: "Erklärung ausblenden",
    game_zoowurf: "Zoowurf",
    home_zoowurf_desc: "Ein Würfelspiel für Kinder: Würfle mit den Tierwürfeln und fülle die Karte mit den Tieren, die sie zeigt – Löwe, Elefant, Giraffe, Affe und Pinguin. Nur Bilder, kein Lesen nötig, kein Zeitlimit. Gegen den Computer oder mit bis zu vier Personen an einem Gerät.",
    zoowurf_history_intro: "Würfeln und Bilder zuordnen gehören zu den ersten Spielen kleiner Kinder – dieses verbindet beides mit Tieren aus dem Zoo.",
    quickrules_zoowurf_1: "Jede Person hat eine eigene Karte. Sie zeigt die Tiere, die du würfeln musst.",
    quickrules_zoowurf_2: "Würfle einmal pro Zug. Würfel mit einem Tier deiner Karte oder der Pfote bleiben auf der Karte.",
    quickrules_zoowurf_3: "Eine volle Karte bringt einen Punkt pro Tier; dann nimm eine offene Karte. Bei 12 Punkten wird die Runde beendet, und die meisten Punkte gewinnen.",
    game_tieryatzy: "Tier-Yatzy",
    home_tieryatzy_desc: "Ein Würfelspiel für Kinder mit Tierwürfeln: bis zu dreimal würfeln, die gewünschten Tiere behalten und den eigenen Block füllen – Löwen, Elefanten, zwei oder mehr Gleiche, alle verschieden. Die Pfote ist ein Joker. Nur Bilder, kein Rechnen. Allein, gegen den Computer oder mit bis zu vier Spielern an einem Gerät.",
    tieryatzy_history_intro: "Fünf Würfel bis zu dreimal werfen und dann wählen, wo man punktet, ist eine alte Würfelspiel-Idee – hier mit Tieren statt Zahlen.",
    quickrules_tieryatzy_1: "Wirf die fünf Tierwürfel. Tippe die Würfel an, die du behalten willst, und wirf die anderen noch einmal – bis zu dreimal.",
    quickrules_tieryatzy_2: "Dann tippe ein freies Feld auf deinem Block an. Die Pfote zählt als jedes Tier. Ein Feld, das nicht passt, bekommt 0 Punkte.",
    quickrules_tieryatzy_3: "Wenn alle Felder voll sind, ist das Spiel aus. Wer die meisten Punkte hat, gewinnt.",
    ty_mode_people: "Personen an einem Gerät",
    ty_goal_line: "Ziel: Fülle alle Felder deines Blocks. Wer die meisten Punkte hat, gewinnt.",
