    game_slidepuzzle: "Schiebepuzzle",
    home_slidepuzzle_desc: "Schiebe die Zahlenplättchen in die richtige Reihenfolge, die Lücke unten rechts. Jedes Rätsel ist lösbar; 3 × 3, 4 × 4 oder 5 × 5, mit Hinweisen und ohne Uhr.",
    slidepuzzle_history_intro: "Ein Kasten mit Zahlenplättchen und einem leeren Platz: 1880 war das Schiebepuzzle in den USA eine Massenbegeisterung.",
    quickrules_slidepuzzle_1: "Tippe ein Plättchen in derselben Zeile oder Spalte wie die Lücke an: Es rutscht in die Lücke, die Plättchen dazwischen rutschen mit.",
    quickrules_slidepuzzle_2: "Bringe die Zahlen der Reihe nach in Ordnung, Zeile für Zeile, die Lücke unten rechts.",
    quickrules_slidepuzzle_3: "Jedes Rätsel ist lösbar. Festgefahren? Der Hinweis-Knopf markiert ein Plättchen zum Schieben.",
    sp_size_label: "Brett:",
    sp_goal_line: "Ziel: die Zahlen der Reihe nach, die Lücke unten rechts.",
    sp_goal_status: "Tippe ein Plättchen neben der Lücke an oder weiter hinten in ihrer Zeile oder Spalte.",
