    game_hanoi: "Türme von Hanoi",
    home_hanoi_desc: "Versetze den ganzen Scheibenturm auf den rechten Stab, immer eine Scheibe, nie eine größere auf eine kleinere. 3 bis 8 Scheiben, Zugzähler, Zurücknehmen und Hinweise.",
    hanoi_history_intro: "Ein Rätsel von 1883 mit einer erfundenen Legende – und einer einfachen Regel für die wenigsten Züge.",
    quickrules_hanoi_1: "Tippe einen Stab an, um seine oberste Scheibe aufzunehmen, dann tippe den Stab an, auf den sie soll.",
    quickrules_hanoi_2: "Eine Scheibe darf nie auf einer kleineren liegen.",
    quickrules_hanoi_3: "Versetze den ganzen Turm auf den rechten Stab (mit dem Stern). Die wenigsten Züge: 2 hoch Scheibenzahl, minus 1.",
    hanoi_discs_label: "Scheiben:",
    hanoi_goal_line: "Ziel: der ganze Turm auf dem rechten Stab.",
