    hanoi_rod_label: "Stab {n}",
    game_nim: "Nim",
    home_nim_desc: "Nehmt abwechselnd Steine von den Haufen – wer den letzten Stein nimmt, gewinnt (oder, bei Misère, verliert). Gegen den Computer in drei Stufen oder zu zweit.",
    nim_history_intro: "Ein Spiel ums Wegnehmen von Steinen, das Charles L. Bouton 1901 benannt und gelöst hat.",
    quickrules_nim_1: "Nimm in deinem Zug einen oder mehrere Steine aus einer Reihe: Tippe den Stein an, bis zu dem du nehmen willst, dann „Steine nehmen“.",
    quickrules_nim_2: "Normal: Wer den letzten Stein nimmt, gewinnt. Misère: Wer den letzten Stein nimmt, verliert.",
    quickrules_nim_3: "Die Zeile unter den Haufen sagt, ob der Start für den Beginnenden gewonnen oder verloren ist. Aus einer Gewinnstellung ist der schwere Computer nicht zu schlagen.",
