    zw_count: "{n} von {m}",
    zw_goal_line: "Ziel: Jedes Tier auf einer vollen Karte ist ein Punkt. Hat jemand 12 Punkte, wird die Runde beendet; die meisten Punkte gewinnen.",
    zw_level_label: "Computer:",
    zw_level_normal: "Normal",
    zw_level_beginner: "Anfänger",
    zw_howto_1: "Jede Person hat eine eigene Karte. Sie zeigt die Tiere, die du brauchst.",
    zw_howto_2: "Würfle einmal pro Zug. Würfel mit einem Tier deiner Karte bleiben darauf.",
    zw_howto_3: "Die Pfote legst du selbst auf ein leeres Tier deiner Wahl.",
    zw_howto_4: "Eine volle Karte bringt einen Punkt pro Tier. Dann nimm eine der zwei offenen Karten. Nach den Zügen der Computer tippst du auf Weiter.",
    game_klappenkasten: "Klappenkasten",
    home_klappenkasten_desc: "Ein traditionelles Würfelspiel: Wirf zwei Würfel und klappe die Zahlen zu, die zusammen deinen Wurf ergeben. Passt nichts mehr, zählen die offenen Klappen gegen dich – die wenigsten Punkte gewinnen, und wer alle Klappen schließt, gewinnt sofort. Gegen den Computer oder mit bis zu vier Spielern an einem Gerät.",
    kk_history_intro: "Ein traditionelles Würfelspiel mit einer Reihe nummerierter Klappen, gespielt in Kneipen und auf Schiffen – wo und wann genau es entstand, ist nicht gesichert.",
    quickrules_klappenkasten_1: "Wirf die zwei Würfel und klappe Zahlen zu, die zusammen den Wurf ergeben – eine Klappe oder mehrere.",
    quickrules_klappenkasten_2: "Würfle und klappe weiter. Passt nichts mehr, sind die Zahlen der offenen Klappen deine Punkte.",
    quickrules_klappenkasten_3: "Die wenigsten Punkte gewinnen; wer alle Klappen schließt, gewinnt sofort. „Rückgängig“ nimmt ein Zuklappen zurück.",
    kk_goal_line: "Ziel: Klappe Zahlen zu, die zusammen deinen Wurf ergeben. Wenige offene Klappen sind wenige Punkte – die wenigsten Punkte gewinnen.",
    kk_howto_1: "Würfle mit den beiden Würfeln.",
    kk_howto_2: "Klappe Klappen zu, die zusammen die Summe ergeben: 8 ist 3 und 5.",
    kk_howto_3: "Würfle noch einmal und klappe weitere zu, solange welche passen.",
    kk_howto_4: "Wenn nichts mehr passt, ist dein Zug zu Ende. Die offenen Klappen sind deine Punkte: Wenigste gewinnt.",
    kk_size_label: "Klappen:",
