    sw_again_hint: "Doppelsechs! Würfle nochmal.",
    game_steckwuerfeln: "Steckwürfeln",
    home_steckwuerfeln_desc: "Ein traditionelles Steck- und Würfelspiel mit elf Löchern von 2 bis 12: Wirf zwei Würfel und stecke in das Loch der Summe oder in die zwei Löcher der einzelnen Würfel. Würfle weiter, bis nichts mehr passt – die freien Löcher zählen gegen dich, die wenigsten Punkte gewinnen. Varianten: Doppelsechs als Joker oder ein gemeinsames Brett, bei dem ausscheidet, wer nicht mehr stecken kann.",
    sw_history_intro: "Ein kleines traditionelles Würfelspiel auf einem Brett mit nummerierten Löchern und Stöpseln – einfach, alt und bis heute als Holz-Taschenspiel zu kaufen.",
    quickrules_steckwuerfeln_1: "Wirf zwei Würfel. Stecke in das Loch der Summe oder in die zwei Löcher der einzelnen Würfel (2 und 4: Loch 6 oder Löcher 2 und 4).",
    quickrules_steckwuerfeln_2: "Würfle und stecke weiter. Passt nichts mehr, sind die Zahlen der freien Löcher deine Punkte.",
    quickrules_steckwuerfeln_3: "Die wenigsten Punkte gewinnen. Doppelsechs ist ein Joker (nochmal würfeln). „Rückgängig“ nimmt einen Stöpsel zurück.",
    sw_goal_line: "Ziel: Stecke Stöpsel in die Löcher. Die freien Löcher zählen als Punkte – die wenigsten Punkte gewinnen.",
    sw_mode_label: "Spiel:",
    sw_mode_score: "Punkte",
    sw_mode_shared: "Gemeinsames Brett",
