    sw_roll: "Zwei Würfel werfen",
    sw_howto_1: "Würfle mit den beiden Würfeln.",
    sw_howto_2: "Stecke in das Loch mit der Summe oder in die beiden Löcher der einzelnen Würfel.",
    sw_howto_3: "In ein Loch passt nur ein Stift. Würfle weiter, solange ein Stift passt.",
    sw_howto_4: "Wenn nichts mehr passt, ist dein Zug zu Ende. Die freien Löcher sind deine Punkte: Wenigste gewinnt.",
