    sw_out_tag: "raus",
    sw_full_message: "Alle Löcher sind gesteckt!",
    sw_shared_message: "Die anderen konnten nicht mehr stecken.",
    game_sternjagd: "Sternjagd",
    home_sternjagd_desc: "Ein Fangspiel für zwei bis vier mit einem Würfel: Die Augenzahl ist genau die Zahl der Schritte entlang der Pfeile eines sternförmigen Bretts. Wer auf einem Gegner landet, nimmt ihm einen seiner drei Sterne; Überspringen ändert nichts. Wer als Letzter noch Sterne hat, gewinnt.",
    sj_history_intro: "Fangspiele mit einem Würfel sind in vielen Kulturen überliefert; diese Fassung hat ein eigenes Brett mit Pfeilen.",
    quickrules_sternjagd_1: "Würfle und ziehe genau so viele Schritte entlang der Pfeile. Tippe auf eines der umrandeten Felder.",
    quickrules_sternjagd_2: "Beende deinen Zug auf einem Gegner, um ihn zu fangen: Er verliert einen Stern und kehrt in eine Ecke zurück. Überspringen ändert nichts.",
    quickrules_sternjagd_3: "Jeder hat drei Sterne. Wer als Letzter noch Sterne hat, gewinnt. „Rückgängig“ nimmt einen Zug zurück.",
    quickrules_sternjagd_4: "Bei zwei Spielern ist der Zweite beim ersten Mal zweimal hintereinander dran (abschaltbar).",
    sj_roll: "Würfeln",
    sj_roll_hint: "Würfle.",
    sj_move_hint: "Tippe auf ein umrandetes Feld. Schritte entlang der Pfeile: {n}.",
