    game_teufelsieben: "Glückskette",
    home_teufelsieben_desc: "Ein Karten-Risikospiel: Decke Karten nacheinander auf und höre rechtzeitig auf. Eine doppelte Zahl lässt dich platzen; Reihen ab vier Zahlen geben Bonuspunkte. Für 2 bis 6 Personen, gegen den Computer oder an einem Gerät.",
    quickrules_teufelsieben_1: "Decke in deinem Zug Karte um Karte auf. Nach der ersten Karte darfst du jederzeit aufhören.",
    quickrules_teufelsieben_2: "Eine doppelte Zahl lässt dich platzen: null Punkte in dieser Runde. Wenn alle dran waren, endet die Runde.",
    quickrules_teufelsieben_3: "Vier oder mehr Zahlen in Folge geben Bonuspunkte. Sonderkarten verändern Karten oder Punkte.",
    ts_history_intro: "Weitermachen oder aufhören? Glückskette ist ein Risikokartenspiel für PaperGames.",
