    game_gipfelwurf: "Gipfelwurf",
    home_gipfelwurf_desc: "Ein Würfelspiel mit Mut und Glück: Wirf vier Würfel, bilde zwei Paare und steige auf sieben Graten nach oben. Weiterwürfeln oder ein Lager aufschlagen – passt kein Paar, ist der Aufstieg des Zuges verloren. Wer zuerst auf drei Gipfeln steht, gewinnt. 2 bis 4 Spieler, gegen den Computer oder an einem Gerät.",
    quickrules_gipfelwurf_1: "Wirf vier Würfel und wähle zwei Paare: Jede Paarsumme bringt deinen Kletterer auf ihrem Grat eine Stufe höher. Höchstens drei Kletterer pro Zug.",
    quickrules_gipfelwurf_2: "Weiterwürfeln oder aufhören: Beim Aufhören werden die Kletterer zu Lagern. Passt kein Paar, ist der Aufstieg dieses Zuges verloren.",
    quickrules_gipfelwurf_3: "Ein Lager auf dem Gipfel sichert dir den Grat. Wer zuerst drei Grate hat (oder zwei, wenn so gewählt), gewinnt.",
    gw_history_intro: "Weiterwürfeln oder Lager aufschlagen? Gipfelwurf ist ein Würfelspiel mit Mut und Glück für PaperGames, aus der alten Familie der Würfelspiele, in denen ein Wurf mehr alles kosten kann.",
