    gw_howto_4: "Passt kein Paar? Dann ist der Aufstieg dieses Zuges verloren.",
    game_advent: "Rätsel-Adventskalender",
    home_advent_desc: "24 Türchen, hinter jedem ein kleines Rätsel: Lichtschalter, Mini-Sudoku, Bilderrätsel, Futoshiki, Hochhäuser und Calcudoku. Ein Türchen öffnet sich an seinem Dezembertag, sobald das vorige gelöst ist.",
    quickrules_advent_1: "Vom 1. bis 24. Dezember öffnet sich jeden Tag ein Türchen. Dahinter wartet ein kleines Rätsel für ein paar Minuten.",
    quickrules_advent_2: "Ein Türchen öffnet sich erst, wenn das vorige gelöst ist. Einen Tag verpasst? Löse die früheren Türchen, dann folgen die späteren.",
    quickrules_advent_3: "Tippe ein Feld an und dann eine Zahl darunter. Beim Bilderrätsel wird ein Feld erst gefüllt, dann angekreuzt, dann wieder leer.",
    adv_history_intro: "Die Tage bis Weihnachten zählen: von Kreidestrichen an der Tür bis zu gedruckten Kalendern mit kleinen Türchen - und hier ein kleines Rätsel am Tag.",
