    adv_kind_calcudoku: "Calcudoku",
    adv_how_lights: "Schalte alle Lichtschalter. Ein Tipp schaltet das Licht und seine Nachbarn oben, unten, links und rechts um.",
    adv_how_sudoku: "In jeder Zeile, jeder Spalte und jedem Kasten steht jede Zahl einmal.",
    adv_how_nonogram: "Die Zahlen nennen der Reihe nach die Blöcke gefüllter Felder in jeder Zeile und Spalte.",
    adv_how_futoshiki: "In jeder Zeile und Spalte steht jede Zahl einmal. Die Zeichen zeigen auf die kleinere Zahl.",
    adv_how_skyscrapers: "In jeder Zeile und Spalte steht jede Zahl einmal; eine Zahl ist die Höhe eines Turms. Ein Hinweis sagt, wie viele Türme man von dort sieht.",
    adv_how_calcudoku: "In jeder Zeile und Spalte steht jede Zahl einmal. Die Zahlen eines Kastens ergeben mit dem Rechenzeichen seinen Wert.",
