    adv_state_on: "an",
    adv_state_off: "aus",
    adv_text_1: "Das erste Türchen ist offen - 23 kommen noch.",
    adv_text_2: "Draußen wird es früh dunkel; ein Rätsel passt gut zu den langen Abenden.",
    adv_text_3: "Eine Tasse Tee und ein Bild aus Kästchen - ein guter Start in den Tag.",
    adv_text_4: "Stück für Stück werden die Tage heruntergezählt.",
    adv_text_5: "Draußen kommt vielleicht der erste Frost; drinnen fügen sich die Zahlen.",
    adv_text_6: "Fast eine Woche Dezember liegt hinter dir.",
    adv_text_7: "Eine Woche Rätsel geschafft - gut durchgehalten.",
    adv_text_8: "Listen, Briefe, kleine Pläne: Der Dezember ist voll - und dieses Türchen ist geschafft.",
    adv_text_9: "Irgendwo fallen gerade die ersten Schneeflocken.",
    adv_text_10: "Zehn Türchen offen - der Kalender füllt sich.",
    adv_text_11: "Kurze Tage, lange Nächte: gute Zeit zum Nachdenken.",
    adv_text_12: "Der halbe Kalender liegt fast hinter dir.",
    adv_text_13: "Ein warmes Getränk, eine ruhige Minute, ein gelöstes Rätsel.",
    adv_text_14: "Zwei Wochen Dezember - der Countdown läuft.",
    adv_text_15: "Irgendwo werden Plätzchen gebacken; hier wird ein Rätsel gelöst.",
    adv_text_16: "Nur noch acht Türchen.",
    adv_text_17: "Helle Fenster in der dunklen Straße - und ein Türchen mehr offen.",
    adv_text_18: "Geschenkpapier, Bänder und noch ein gelöstes Rätsel.",
    adv_text_19: "Das Jahr ist fast vorbei; die Rätsel halten dich wach.",
    adv_text_20: "Zwanzig Türchen - nur noch vier.",
    adv_text_21: "Nur noch drei Türchen - der Kalender ist fast voll.",
    adv_text_22: "Fast geschafft: noch ein paar Türchen, dann ist der Kalender voll.",
    adv_text_23: "Der Tag vor dem letzten Türchen - schön, dass du so weit gekommen bist.",
    adv_text_24: "Alle 24 Türchen sind offen. Schöne Feiertage und eine friedliche Zeit!",
    sj_last_capture: "{name}: {n} gewürfelt, {victim} gefangen: ein Stern weniger.",
    sj_last_pass: "{name}: {n} gewürfelt, kein Feld passt.",
