    game_kleeberg: "Kleeberg",
    home_kleeberg_desc: "Ein Bauspiel für zwei auf einer Pyramide aus runden Feldern: Abwechselnd Herzen oder Kleeblätter auf freie Felder setzen, aber nur auf zwei gefüllte Felder. Drei eigene Zeichen in einer geraden Linie gewinnen.",
    kb_history_intro: "Kleeberg ist ein neues Spiel mit eigenen Regeln; es baut auf der alten Idee „drei in einer Reihe“ auf.",
    quickrules_kleeberg_1: "Abwechselnd: Setze ein Herz oder ein Kleeblatt auf ein umrandetes Feld.",
    quickrules_kleeberg_2: "Baue nach oben: Ein Feld ist nur offen, wenn beide Felder darunter gefüllt sind.",
    quickrules_kleeberg_3: "Drei eigene Zeichen in einer geraden Linie gewinnen. Ist die Pyramide voll und niemand hat eine Linie, gibt es ein Unentschieden.",
    kb_move_hint: "Tippe auf ein umrandetes Feld. Felder mit gestricheltem Rand sind noch nicht offen.",
    kb_hearts: "Herzen",
    kb_clovers: "Kleeblätter",
    kb_board_aria: "Pyramide aus fünfzehn runden Feldern in fünf Reihen",
    kb_goal_aria: "Beispiel: drei Herzen in einer geraden Linie",
    kb_goal_text: "Ziel: drei eigene Zeichen in einer geraden Linie.",
    kb_field_name: "Reihe {r}, Feld {c}",
    kb_field_move: "frei, tippen zum Bauen",
    kb_field_locked: "noch nicht offen",
    kb_over_message: "Drei in einer geraden Linie gewinnen. Eine volle Pyramide ohne Linie ist ein Unentschieden.",
    kq_cards_label: "Karten",
    game_oddone: "Was passt nicht?",
    home_oddone_desc: "Mehrere Karten sind in einer Hinsicht gleich – bis auf eine: Tippe die an, die nicht dazugehört. Zeichnungen aus derselben Gruppe oder Formen, die in einem Merkmal übereinstimmen. Sechs Runden pro Spiel, drei Stufen, große Knöpfe, ohne Zeitlimit, bei Bedarf mit Tipp.",
    oddone_history_intro: "Das Teil zu finden, das nicht passt, ist eine klassische Übung in Schulbüchern und Denktests – sie trainiert, Dinge nach ihren Merkmalen zu ordnen.",
    quickrules_oddone_1: "Mehrere Karten sind in einer Hinsicht gleich – bis auf eine.",
    quickrules_oddone_2: "Tippe die Karte an, die nicht dazugehört. Eine falsche wird durchgestrichen – probiere eine andere.",
    quickrules_oddone_3: "Sechs Runden sind ein Spiel. Es gibt kein Zeitlimit, und der Tipp markiert die Karte, die nicht passt.",
    od_win_title: "Alle Runden geschafft!",
    msg_od_start: "Welche Karte passt nicht? Tippe sie an.",
    msg_od_wrong: "Diese gehört zu den anderen. Probiere eine andere.",
    msg_od_hint: "Tipp: Die markierte Karte passt nicht.",
    msg_t_od_won: "Alle Runden geschafft! Fehler: {n}.",
    msg_t_od_won_modal: "Alle Runden geschafft. Fehler: {n}.",
    msg_t_od_info: "Runde {n} von {m} · Fehler: {k}",
    msg_t_od_aria_option: "Karte {n}",
    msg_t_od_aria_wrong: "Karte {n}, nicht richtig",
    msg_t_od_aria_right: "Karte {n}, richtig",
    kq_shadows_label: "Schatten",
    family_picturelogic: "Bilderrätsel zum Denken",
    game_shadowmatch: "Wessen Schatten ist das?",
    home_shadowmatch_desc: "Ein Bild und mehrere schwarze Schatten: Welcher Schatten gehört dazu? Sechs Bilder pro Spiel, drei Stufen – auf Schwer erscheint dasselbe Bild auch gedreht oder gespiegelt. Große Knöpfe, ohne Zeitlimit, bei Bedarf mit Tipp.",
    shadowmatch_history_intro: "Schatten werden seit Jahrhunderten nachgezeichnet, ausgeschnitten und zum Spielen benutzt – einen Schatten seinem Gegenstand zuzuordnen ist eine kleine Übung im genauen Hinschauen.",
    quickrules_shadowmatch_1: "Oben ist ein Bild, darunter sind schwarze Schatten.",
    quickrules_shadowmatch_2: "Tippe den Schatten an, der genau den Umriss des Bildes hat. Ein falscher wird durchgestrichen – probiere einen anderen.",
    quickrules_shadowmatch_3: "Sechs Bilder sind ein Spiel. Es gibt kein Zeitlimit, und der Tipp markiert den richtigen Schatten.",
    sm_win_title: "Alle Bilder geschafft!",
    msg_sm_start: "Welcher Schatten gehört zum Bild? Tippe ihn an.",
    msg_sm_wrong: "Dieser Schatten passt nicht. Probiere einen anderen.",
    msg_sm_hint: "Tipp: Der markierte Schatten ist der richtige.",
    msg_t_sm_won: "Alle Bilder geschafft! Fehler: {n}.",
    msg_t_sm_won_modal: "Alle Bilder geschafft. Fehler: {n}.",
    msg_t_sm_info: "Bild {n} von {m} · Fehler: {k}",
    msg_sm_aria_picture: "Bild",
    msg_t_sm_aria_option: "Schatten {n}",
    msg_t_sm_aria_wrong: "Schatten {n}, nicht richtig",
    msg_t_sm_aria_right: "Schatten {n}, richtig",
    kq_next: "Weiter",
    kq_level_label: "Stufe",
    kq_answers_label: "Antworten",
    game_patternrow: "Muster fortsetzen",
    home_patternrow_desc: "Eine Reihe von Zeichen folgt einem Muster – welches Zeichen kommt als Nächstes? Sechs Reihen pro Spiel, drei Stufen, Formen in Schwarz und Weiß, große Antwortknöpfe. Ohne Zeitlimit, bei Bedarf mit Tipp.",
    patternrow_history_intro: "Reihen aus wiederkehrenden Zeichen sind so alt wie Töpferei und Weberei – und sie fortzusetzen ist eine beliebte Aufgabe in Schulbüchern und Tests.",
    quickrules_patternrow_1: "Eine Reihe von Zeichen wiederholt sich nach einem Muster; der letzte Platz ist leer.",
    quickrules_patternrow_2: "Tippe das Zeichen an, das auf den leeren Platz gehört. Ein falsches wird durchgestrichen – probiere ein anderes.",
    quickrules_patternrow_3: "Sechs Reihen sind ein Spiel. Es gibt kein Zeitlimit, und der Tipp markiert das richtige Zeichen.",
    pr_win_title: "Alle Reihen geschafft!",
    msg_pr_start: "Welches Zeichen kommt als Nächstes? Tippe auf die Antwort.",
    msg_pr_wrong: "Das ist es nicht. Probiere ein anderes.",
    msg_pr_right: "Richtig! Tippe auf „Weiter“.",
