    msg_aw_glided: "Der Pfeil gleitet bis zum nächsten Pfeil vor.",
    msg_aw_heart: "Das hat ein Herz gekostet.",
    msg_aw_stuck: "Kein Pfeil kann sich mehr bewegen – mach ein paar Züge rückgängig.",
    msg_aw_lost: "Keine Herzen mehr – versuch diese Aufgabe noch einmal oder starte eine neue.",
    msg_aw_noway: "Von hier gibt es keinen Ausweg – mach ein paar Züge rückgängig.",
