    msg_t_aw_info_hearts: "Pfeile übrig: {n} · Züge: {m} · Herzen: {k}",
    game_catplaces: "Katzenplätze",
    home_catplaces_desc: "In jede Zeile, jede Spalte und jeden Raum kommt genau eine Katze – und zwei Katzen dürfen sich nicht berühren, auch nicht an einer Ecke. Logikrätsel in drei Größen, jedes mit genau einer Lösung, ohne Raten lösbar.",
    kz_history_intro: "Die Regeln stammen von einem Logikrätsel, das 2003 für die Rätsel-Weltmeisterschaft in den Niederlanden erfunden wurde; hier nehmen schlafende Katzen den Platz der Sterne ein.",
    quickrules_catplaces_1: "Setze in jede Zeile, jede Spalte und jeden Raum (die Flächen innerhalb der dicken Linien) eine Katze.",
    quickrules_catplaces_2: "Zwei Katzen dürfen sich nie berühren – nicht nebeneinander und nicht an einer Ecke.",
    quickrules_catplaces_3: "Tippe ein Feld einmal für eine Katze an, noch einmal für einen Punkt (hier keine Katze), ein drittes Mal zum Leeren. „Tipp“ zeigt ein Feld.",
    kz_win_title: "Gelöst!",
