    msg_kz_start: "Tippe ein Feld an: einmal für eine Katze, noch einmal für einen Punkt, ein drittes Mal zum Leeren.",
    msg_kz_conflict: "Zwei Katzen teilen sich eine Zeile, Spalte oder einen Raum oder berühren sich – siehe die gestrichelten Rahmen.",
    msg_kz_hint_place: "Tipp: Im markierten Feld gehört eine Katze hin.",
