    msg_t_aw_info: "Pfeile übrig: {n} · Züge: {m} · Mindestens: {k}",
    game_rings: "Ringe drehen",
    home_rings_desc: "Drei bis fünf Ringe ineinander, darauf Formen. Drehe die Ringe, bis jeder Strahl von der Mitte aus dieselbe Form zeigt – auf Schwer dreht ein Ring seinen Nachbarn mit. Mit Mindestzahl der Züge und Tipp-Knopf.",
    rg_history_intro: "Ringe mit Zeichen, die gegeneinander gedreht werden, sind alt: Leon Battista Alberti beschrieb 1467 eine Chiffrierscheibe aus zwei drehbaren Ringen. Das Rätsel hier ist für PaperGames gemacht.",
    quickrules_rings_1: "Drehe einen Ring mit den Knöpfen unter dem Bild nach links ↺ oder rechts ↻.",
    quickrules_rings_2: "Ziel: Jeder der 8 Strahlen von der Mitte nach außen zeigt auf allen Ringen dieselbe Form.",
    quickrules_rings_3: "Auf Schwer dreht ein Ring den nächsten Ring nach außen mit. „Tipp“ zeigt einen guten Zug; die Mindestzahl der Züge steht dabei.",
    rg_win_title: "Gelöst!",
