    game_matches: "Streichholzrätsel",
    home_matches_desc: "Lege ein oder zwei Hölzer um, damit eine falsche Rechnung stimmt oder die Figur die verlangte Zahl von Quadraten zeigt. 90 Aufgaben in drei Stufen, jede vom Computer geprüft; Holz antippen, dann einen freien Platz – ohne Ziehen.",
    mt_history_intro: "Streichhölzer wurden im 19. Jahrhundert alltäglich und bald auch Rätselstoff: Professor Hoffmanns Buch Puzzles Old and New (1893) hat schon ein Kapitel mit Streichholzrätseln.",
    quickrules_matches_1: "Tippe ein Holz an, um es aufzunehmen, dann einen freien Platz, um es dort abzulegen.",
    quickrules_matches_2: "Lege genau so viele Hölzer um, wie die Aufgabe sagt: 1 oder 2.",
    quickrules_matches_3: "Mach die Rechnung richtig oder lege die verlangte Zahl von Quadraten. Rückgängig, Neu anfangen und Tipp helfen.",
