    game_tangram: "Tangram",
    home_tangram_desc: "Fülle einen Umriss mit den sieben klassischen Teilen – Dreiecke, ein Quadrat und ein Parallelogramm. 90 Umrisse in vier Stufen, jeder mit einer vom Computer geprüften Lösung. Bei „Nur Umriss“ siehst du nur die äußere Linie, und ein Teil bleibt dort liegen, wo du tippst – du musst probieren. Teil antippen, drehen, Ziel antippen – kein Ziehen.",
    tg_history_intro: "Sieben Teile, aus einem Quadrat geschnitten: Das Rätsel stammt aus China, wo das älteste erhaltene Buch darüber 1813 gedruckt wurde; ab 1817 wurde es in Europa große Mode.",
    quickrules_tangram_1: "Wähle ein Teil unter dem Umriss, drehe es mit „Drehen 45°“ oder spiegle es, dann tippe dorthin, wohin es gehört.",
    quickrules_tangram_2: "Fülle den ganzen Umriss mit allen sieben Teilen; sie dürfen sich nicht überlappen.",
    quickrules_tangram_3: "Tippe ein gelegtes Teil an, um es wieder aufzunehmen. „Tipp“ legt ein Teil an die richtige Stelle.",
